  nodes.add instr("BRK", amImmediate8, 0x0)  # $EFFFEF: BRK #$00
  nodes.add instr("BRK", amImmediate8, 0x0)  # $EFFFF1: BRK #$00
  nodes.add instr("BRK", amImmediate8, 0x0)  # $EFFFF3: BRK #$00
  nodes.add instr("BRK", amImmediate8, 0x0)  # $EFFFF5: BRK #$00
  nodes.add instr("BRK", amImmediate8, 0x0)  # $EFFFF7: BRK #$00
  nodes.add instr("BRK", amImmediate8, 0x0)  # $EFFFF9: BRK #$00
  nodes.add instr("BRK", amImmediate8, 0x0)  # $EFFFFB: BRK #$00
  nodes.add instr("BRK", amImmediate8, 0x0)  # $EFFFFD: BRK #$00
  result = assemble(nodes, 0xEFFF0F'u32,
                    FlagState(m8: true, x8: true, emulation: true))

  # Trailing bytes the linear decode could not cover as whole
  # instructions (region boundary cuts mid-instruction).
  # TODO: refine the region boundary when the code map improves.
  result.add @[0x00'u8]

